import * as React from "react";
import dynamic from "next/dynamic";
import {
  PlasmicLoaction,
  DefaultLoactionProps
} from "./plasmic/sayban/PlasmicLoaction";
import { HTMLElementRefOf } from "@plasmicapp/react-web";
import { useAddCenterAttempted } from "./centerPanel/addCenterValidationStore";
import { getLocationFieldErrors } from "./centerPanel/validateCenterWizard";
import fieldStyles from "./centerPanel/CenterOwnerInfoForm.module.css";
import styles from "./Loaction.module.css";

const NeshanMapPicker = dynamic(() => import("./NeshanMapPicker"), {
  ssr: false,
  loading: () => (
    <div className={styles.mapStage}>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          height: "100%",
          color: "#6b7280",
          fontSize: 14
        }}
      >
        در حال بارگذاری نقشه...
      </div>
    </div>
  )
});

/** Plasmic keeps lat/lon as internal state (onChange only); expose for the map. */
export interface LoactionProps extends DefaultLoactionProps {
  lat?: string | number;
  lon?: string | number;
}

function Loaction_(props: LoactionProps, ref: HTMLElementRefOf<"div">) {
  const { lat, lon, className: classNameProp, ...plasmicProps } = props;
  const attempted = useAddCenterAttempted();
  const errors = getLocationFieldErrors({
    address: props.address,
    city: props.city2,
    state: props.state2,
    phone: props.call2
  });

  const className = [classNameProp, styles.rootFix].filter(Boolean).join(" ");

  return (
    <PlasmicLoaction
      root={{ ref }}
      {...plasmicProps}
      className={className}
      overrides={{
        call: {
          props: {
            error: attempted && errors.phone ? "error" : undefined,
            ariaLabel: attempted && errors.phone ? errors.phone : undefined
          }
        },
        loaction: {
          props: {
            error: attempted && errors.address ? "error" : undefined,
            ariaLabel: attempted && errors.address ? errors.address : undefined
          }
        },
        // Replace the fragile Plasmic Embed HTML map (fixed #map id, CDN script
        // in modal/tab with zero size) with the shared React Neshan picker.
        embedHtml: {
          render: () => (
            <div className={styles.mapStage}>
              <NeshanMapPicker
                initialLat={lat}
                initialLng={lon}
                onLocationChange={location => {
                  props.onLatChange?.(String(location.lat));
                  props.onLonChange?.(String(location.lng));
                  if (location.address) {
                    props.onAddressChange?.(location.address);
                  }
                  if (location.city) {
                    props.onCityChange?.(location.city);
                  }
                  if (location.state) {
                    props.onStateChange?.(location.state);
                  }
                }}
              />
            </div>
          )
        },
        root: {
          wrapChildren: (children: React.ReactNode) => (
            <>
              {children}
              {attempted &&
              (errors.address || errors.city || errors.state || errors.phone) ? (
                <div
                  className={fieldStyles.root}
                  style={{ marginTop: "0.75rem" }}
                  role="alert"
                >
                  {errors.state ? (
                    <div className={fieldStyles.error}>{errors.state}</div>
                  ) : null}
                  {errors.city ? (
                    <div className={fieldStyles.error}>{errors.city}</div>
                  ) : null}
                  {errors.address ? (
                    <div className={fieldStyles.error}>{errors.address}</div>
                  ) : null}
                  {errors.phone ? (
                    <div className={fieldStyles.error}>{errors.phone}</div>
                  ) : null}
                </div>
              ) : null}
            </>
          )
        }
      }}
    />
  );
}

const Loaction = React.forwardRef(Loaction_);
export default Loaction;
